sketches.source:
setcpm(132/4)

// The form: an intro, the head and a turnaround, the head again into a solo chorus, a last head and an outro
song("intro@4 (head@8 1.turn@4 2.solo@16)*2 head'@8 outro@4", "once")
// A ritardando over the outro
tempomap("0:33 48:33 52:24")

// The walking bass and a feathered kick stay dead centre: Gm7, C7, Fmaj7, D7
bass: note("<[g1 bb1 d2 f2] [c2 e2 g2 bb2] [f1 a1 c2 e2] [d2 f#2 a2 c3]>")
  .s("sine").shape(.15).decay(.3).sustain(.3).release(.1).gain(.5).exceptSections("intro")
kick: s("bd*4").lpf(200).gain(.3).exceptSections("intro outro")

// The kit is set up around you: the ride on your right, the hats on your left
// The hats double up in the last bar of every section, a small fill into the next
ride: s("rd [rd@2 rd] rd [rd@2 rd]").azimuth(50).distance(2).gain(.24).exceptSections("intro")
hats: s("~ hh ~ hh").azimuth(-50).distance(2).gain(.26).atEnd(1, x => x.ply(2))

// Brushes sweep a circle around your head every two bars, a little louder when the band thins out
brushes: s("pink*8").hpf(3000).lpf(8000).decay(.08).sustain(0).swing(4)
  .azimuth(saw.range(-180, 180).slow(2)).distance(1.5).posglide(.3)
  .gain(bysec("intro:.07 outro:.07 *:.05"))

// Piano comping a little to the left, leaning in on the turnaround
piano: note("<[f3,a3,bb3,d4] [e3,g3,bb3,d4] [e3,a3,c4,d4] [f#3,a3,c4,eb4]>")
  .struct("~ [~@2 x] ~ x").s("triangle").timbre("soft")
  .decay(.4).sustain(.1).release(.3).azimuth(-25).distance(2.5).room(.3)
  .gain(bysec("turn:.26 *:.22"))

// The saxophone straight ahead: the head, brighter on its last time through
const tenor = x => x.s("sawtooth").timbre("reed").vowel("o").lpf(2400).vib(5).vibdepth(.12)
  .attack(.03).sustain(.6).release(.2).distance(3).room(.4).gain(.22)
sax: tenor(note("<[d5@2 c5 bb4 a4@2 g4@2] [bb4@3 a4 g4 e4@3] [a4@4 c5@2 e5@2] [d5@2 c5 a4 f#4@4]>"))
  .sections("head").variant(x => x.lpf(3600).vibdepth(.2))

// In the solo chorus the saxophone improvises over the changes, a few notes left out
solo: tenor(n("0 2 4 [6 4] 7 5 [4 2] 1").add("<1 4 0 5>").scale("F:major").transpose(12)
  .degradeBy(.2).seed("solo")).sections("solo")

setcpm(60/4)

// Piano alone, the tune twice, a coda and one last chord, slowing down at the end
song("intro@4 tune@8 tune'@8 coda@3 last@1", "once")
tempomap("0:15 20:15 24:9")

// A ballad in Eb: Ebmaj7, Cm7, Fm7, Bb7
// From about 1 to 30 ms the piano stays on the leading side but grows wider each bar
// Each section restarts the progression, so the last bar lands on Ebmaj7
piano: note("<[eb3 g3 bb3 d4 g4 d4 bb3 g3] [c3 eb3 g3 bb3 eb4 bb3 g3 eb3] [f3 ab3 c4 eb4 ab4 eb4 c4 ab3] [bb2 d3 f3 ab3 d4 ab3 f3 d3]>")
  .s("triangle").timbre("soft").attack(.005).decay(1).sustain(.1).release(1.2)
  .itd("<1 8 15 25>").room(bysec("coda:.7 last:.8 *:.5")).gain(.26)

// The tenor sax stands in the middle with no delay at all; the second time an octave lower and darker
tenor: note("<[g4@3 f4 eb4@4] [eb4@2 g4 bb4 c5@4] [ab4@3 g4 f4@2 eb4 c4] [d4@6 ~@2]>")
  .s("sawtooth").timbre("reed").vowel("o").lpf(1800).mono(1).glide(.06)
  .vib(4.5).vibdepth(.15).attack(.08).sustain(.7).release(.6).room(.5).gain(.24)
  .sections("tune").variant(x => x.add(-12).lpf(1200))

// Under about 0.7 ms the delay moves a sound sideways: the brushes sway from ear to ear
brushes: s("pink*8").hpf(2500).decay(.1).sustain(0).swing(4)
  .itd(sine.range(-.6, .6).slow(2)).gain(.05).exceptSections("intro last")

// A soft, centred bass
bass: note("<eb2 c2 f2 bb1>").s("sine").attack(.05).decay(.8).sustain(.4).release(.6).gain(.4)
  .exceptSections("intro")

setcpm(120/4)

// An intro, D dorian and the lift to Eb dorian twice, a last stretch of D and an outro
song("intro@4 (vamp@8 lift@8)*2 vamp'@8 outro@4", "once")
tempomap("0:30 44:30 48:22")

// The key follows the form: every lift section moves up a half step
const key = bysec("lift:Eb:dorian *:D:dorian")
const up = bysec("lift:1 *:0")

// A centred kit: ride, hats on two and four, a lazy kick, a fill at the end of each section
drums: stack(
  s("rd [rd@2 rd] rd [rd@2 rd]").gain(.24),
  s("~ hh ~ hh").gain(.22),
  s("bd ~ ~ ~ ~ ~ [~ bd?0.4] ~").lpf(250).seed("modal").gain(.3)
).exceptSections("intro outro").atEnd(1, x => x.ply(2))
bass: n("0 4 6 [3 2]").scale(key).sub(12)
  .s("sine").shape(.15).decay(.3).sustain(.3).release(.1).gain(.48).exceptSections("intro")

// Quartal chords: 0 degrees centred, 90 looser, 180 diffuse and nearly gone in mono
// The filter opens through every section
pad: note("[e3,a3,d4,g4]").add(up).s("sawtooth").unison(3).detune(.2)
  .iphase("<0 90 180 90>").lpf(env("700 2400", "section"))
  .attack(.6).sustain(.8).release(1).room(.5).gain(.14)
comp: note("[e3,a3,d4,g4]").struct("~ ~ x ~ ~ [~ x] ~ ~").add(up)
  .s("sine").fm(1.1).fmh(2).decay(.5).sustain(.2).release(.3).lpf(2400).gain(.2)
  .exceptSections("intro outro")

// A vibraphone drone whose phase between the ears turns a quarter to one time a second
vibes: note("[d4,a4]").add(up).s("sine").fm(2).fmh(4).irate("<.25 .5 1 .5>")
  .attack(.5).sustain(.7).release(1).gain(.1)

// The trumpet plays the theme, straight ahead; on the last vamp it breaks into doubled notes
trumpet: n("<[4@3 3 2@2 0@2] [1@4 ~@4] [4@2 5 6 7@4] [6@2 4@2 3@4]>").scale(key).transpose(12)
  .s("sawtooth").timbre("bright").lpf(2600).mono(1).glide(.04).vib(5).vibdepth(.08)
  .attack(.02).sustain(.6).release(.2).room(.4).gain(.2)
  .sections("vamp lift").variant(x => x.ply(2).degradeBy(.4).seed("vamp"))

setcpm(96/4)

// Listen first, then the ghosts; the first time the vibraphone reveals them,
// the second time the bass and ride drop out and the noise is left alone with the kick
song("intro@4 (ghost@8 1.reveal@8 2.alone@8)*2 coda@3", "once")
tempomap("0:24 36:24 39:16")

// A centred walking bass and kick: Dm7, G7, Cmaj7, A7
bass: note("<[d2 f2 a2 c3] [g1 b1 d2 f2] [c2 e2 g2 b2] [a1 c#2 e2 g2]>")
  .s("sine").shape(.15).decay(.3).sustain(.3).release(.1).gain(.46).exceptSections("alone")
kick: s("bd*4").lpf(200).gain(.26)
ride: s("rd [rd@2 rd] rd [rd@2 rd]").gain(.18).exceptSections("intro alone")

// The brushes: the same noise in both ears, but one ear is phase-shifted in a narrow band
// Neither ear alone hears a tone; together they hear the chord tones
ghost: s("[~ white]*4").dichotic("<[349 440 523 440] [349 494 587 494] [330 392 494 392] [277 330 392 330]>")
  .dichoticq(30).attack(.005).sustain(1).release(.05).gain(.14)
  .sections("ghost reveal alone")

// The hint: the same tones on a vibraphone, quieter when it plays alongside the ghosts
// The coda restarts the changes and stops on Cmaj7
hint: note("<[~ f4 ~ a4 ~ c5 ~ a4] [~ f4 ~ b4 ~ d5 ~ b4] [~ e4 ~ g4 ~ b4 ~ g4] [~ c#4 ~ e4 ~ g4 ~ e4]>")
  .s("sine").fm(2).fmh(4).decay(.3).sustain(0).release(.4)
  .gain(bysec("reveal:.06 *:.1")).sections("intro reveal coda")

setcpm(168/4)

// The head, three solo choruses with new draws each time, the head again and a tag
song("intro@4 head@8 solo@16 solo'@16 solo''@8 head'@8 tag@4", "once")
tempomap("0:42 60:42 64:30")

// A fast, centred kit with a fill into every section
drums: stack(
  s("rd [rd@2 rd] rd [rd@2 rd]").gain(.24),
  s("~ hh ~ hh").gain(.22),
  s("bd ~ ~ ~ ~ ~ ~ ~, ~ ~ ~ sd?0.3 ~ ~ ~ ~").seed("bop").gain(.3)
).exceptSections("intro").atEnd(1, x => x.ply(2))

// A low-pass on each ear alone, sweeping in opposite directions every four bars
// The level stays put; only the brightness wanders: Gm7, C7, Fmaj7, D7
const bright = x => x.s("sawtooth").lpq(4)
  .lcutoff(saw.range(400, 4000).slow(4)).rcutoff(isaw.range(400, 4000).slow(4))
  .decay(.15).sustain(.3).release(.05).swing(4).gain(.18)
line: bright(n("0 2 4 6 7 5 4 3").add("<1 4 0 5>").scale("F:major").transpose(12))
  .sections("head tag")

// The solo choruses: a busier line with a few notes left out
solo: bright(n("0 [2 3] 4 6 [7 9] 8 [6 4] 2").add("<1 4 0 5>").scale("F:major").transpose(12)
  .degradeBy(.15).seed("chorus")).sections("solo")

// A high-pass on the right ear only: the comping sounds fuller on the left
comp: note("<[f3,a3,bb3,d4] [e3,g3,bb3,d4] [e3,a3,c4,d4] [f#3,a3,c4,eb4]>").struct("~ [~@2 x] ~ x")
  .s("triangle").rhcutoff(1200).decay(.4).sustain(.2).release(.3).room(.3).gain(.2)

bass: note("<[g1 bb1 d2 f2] [c2 e2 g2 bb2] [f1 a1 c2 e2] [d2 f#2 a2 c3]>")
  .s("sine").shape(.15).decay(.3).sustain(.3).release(.1).gain(.46)
